// HasGrants applies the HasEdge predicate on the "grants" edge.
func HasGrants() predicate.RewardSkin {
	return predicate.RewardSkin(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, GrantsTable, GrantsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasGrantsWith applies the HasEdge predicate on the "grants" edge with a given conditions (other predicates).
func HasGrantsWith(preds ...predicate.UserRewardGrant) predicate.RewardSkin {
	return predicate.RewardSkin(func(s *sql.Selector) {
		step := newGrantsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RewardSkin) predicate.RewardSkin {
	return predicate.RewardSkin(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RewardSkin) predicate.RewardSkin {
	return predicate.RewardSkin(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RewardSkin) predicate.RewardSkin {
	return predicate.RewardSkin(sql.NotPredicates(p))
}
